"""Metric layer: token-level AUROC/AUPRC (micro over all test tokens) and
document-level AUROC/AUPRC from mean-aggregated token scores (Eq. 3 / R5)."""
from __future__ import annotations

import numpy as np
from sklearn.metrics import average_precision_score, roc_auc_score


def token_level_metrics(scores: np.ndarray, labels) -> dict:
    y = np.asarray([int(v) for v in labels])
    s = np.asarray(scores, dtype=np.float64)
    assert len(y) == len(s), (len(y), len(s))
    assert set(np.unique(y).tolist()) <= {0, 1}
    if len(np.unique(y)) < 2:
        return {"auroc": float("nan"), "auprc": float("nan"), "n": int(len(y)),
                "n_positive": int(y.sum())}
    return {
        "auroc": float(roc_auc_score(y, s)),
        "auprc": float(average_precision_score(y, s)),
        "n": int(len(y)),
        "n_positive": int(y.sum()),
    }


def document_scores(token_scores: np.ndarray, doc_token_counts) -> np.ndarray:
    """Mean aggregation of the token scores of each document (Eq. 3 / R5)."""
    out, i = [], 0
    for c in doc_token_counts:
        c = int(c)
        out.append(float(np.mean(token_scores[i:i + c])))
        i += c
    assert i == len(token_scores), (i, len(token_scores))
    return np.asarray(out, dtype=np.float64)


def document_level_metrics(doc_scores: np.ndarray, doc_labels) -> dict:
    y = np.asarray([int(v) for v in doc_labels])
    s = np.asarray(doc_scores, dtype=np.float64)
    if len(np.unique(y)) < 2:
        return {"auroc": float("nan"), "auprc": float("nan"), "n": int(len(y)),
                "n_positive": int(y.sum())}
    return {
        "auroc": float(roc_auc_score(y, s)),
        "auprc": float(average_precision_score(y, s)),
        "n": int(len(y)),
        "n_positive": int(y.sum()),
    }


def random_control(labels, seed: int = 12345) -> dict:
    """Random token scores must give AUROC ~0.5 and AUPRC ~ positive rate."""
    rng = np.random.RandomState(seed)
    y = np.asarray([int(v) for v in labels])
    s = rng.rand(len(y))
    return token_level_metrics(s, y)


def metric_parity_check() -> dict:
    """Verify the AUROC/AUPRC plumbing against sklearn on synthetic labels."""
    rng = np.random.RandomState(0)
    y = rng.randint(0, 2, 500)
    s = rng.rand(500)
    m = token_level_metrics(s, y)
    return {
        "auroc": m["auroc"],
        "auroc_sklearn": float(roc_auc_score(y, s)),
        "auprc": m["auprc"],
        "auprc_sklearn": float(average_precision_score(y, s)),
        "match": bool(abs(m["auroc"] - roc_auc_score(y, s)) < 1e-12
                      and abs(m["auprc"] - average_precision_score(y, s)) < 1e-12),
    }

